// === Perf Benchmark Harness === (Stage 4)
void AppGL::enableBenchmarkMode(float durationSec, const std::string& outPath,
                                const std::string& comparePath) {
  m_benchmarkMode = true;
  m_benchmarkDuration = (durationSec > 0.0f) ? durationSec : 30.0f;
  m_benchmarkOutPath = outPath.empty() ? "benchmark_results.json" : outPath;
  m_benchmarkComparePath = comparePath;
  m_benchmarkElapsed = 0.0f;
  m_benchmarkRouteIndex = 0;
  m_benchmarkStationTimer = 0.0f;
  m_benchmarkTotalFrames = 0;
  m_benchmarkExitCode = 0;
  m_benchmarkDone = false;
  m_benchmarkCollector.clear();
  m_inMenu = false;
  m_hideUI = true;
  m_benchmarking = false;
  m_userOverrodePreset = true;
  static const char* kRoute[] = {"sol", "sgra", "qso-3c273", "m13", "m16"};
  teleportToStation(kRoute[0]);
}

// === Безопасный режим (--safe) ===
// Для слабых GPU (например, старые карты AMD, где игра показывала белый
// экран и закрывалась): минимальный пресет рендера, без FXAA и тяжёлых
// пост-эффектов. Пользователь может потом поднять настройки вручную.
void AppGL::applySafeMode() {
  if (m_sceneManager) {
    m_sceneManager->applyPreset(PerfPreset::Low);
  }
  m_aaMode = 0;
  if (m_sceneManager) {
    m_sceneManager->setFxaa(false);
  }
  m_userOverrodePreset = true;
}

void AppGL::updateBenchmark(float deltaTime, const std::string& currentStationId) {
  if (!m_benchmarkMode || m_benchmarkDone) return;
  m_benchmarkElapsed += deltaTime;
  m_benchmarkStationTimer += deltaTime;
  m_benchmarkTotalFrames += 1;
  m_benchmarkCollector.recordFrame(deltaTime, currentStationId);

  static const char* kRoute[] = {"sol", "sgra", "qso-3c273", "m13", "m16"};
  const int kRouteSize = 5;
  float perStation = m_benchmarkDuration / static_cast<float>(kRouteSize);
  if (perStation < 1.0f) perStation = 1.0f;
  if (m_benchmarkStationTimer >= perStation) {
    m_benchmarkStationTimer = 0.0f;
    m_benchmarkRouteIndex += 1;
    if (m_benchmarkRouteIndex < kRouteSize) {
      teleportToStation(kRoute[m_benchmarkRouteIndex]);
    }
  }
  if (m_benchmarkElapsed >= m_benchmarkDuration) {
    finalizeBenchmark();
  }
}

void AppGL::finalizeBenchmark() {
  if (m_benchmarkDone) return;
  m_benchmarkDone = true;
  BenchmarkResult res = m_benchmarkCollector.computeResults();
  std::string json = m_benchmarkCollector.serializeJson(res);
  {
    std::ofstream out(m_benchmarkOutPath);
    out << json;
  }
  std::string report = m_benchmarkCollector.formatAsciiReport(res);
  std::cout << report;
  int exitCode = 0;
  if (!m_benchmarkComparePath.empty()) {
    std::string cmpReport;
    bool ok = m_benchmarkCollector.compareWithBaseline(
        res, m_benchmarkComparePath, 10.0f, cmpReport);
    std::cout << cmpReport << "\n";
    if (!ok) exitCode = 1;
  }
  m_benchmarkExitCode = exitCode;
}

void AppGL::drawBenchmarkOverlay() {
  if (!m_benchmarkMode || m_benchmarkDone) return;
  static const char* kRoute[] = {"sol", "sgra", "qso-3c273", "m13", "m16"};
  const int kRouteSize = 5;
  (void)kRoute;
  (void)kRouteSize;
  const Station* curSt = m_sceneManager->getCurrentStation();
  std::string curId = curSt ? curSt->id : std::string("?");
  float pct = (m_benchmarkDuration > 0.0f)
                  ? (m_benchmarkElapsed / m_benchmarkDuration * 100.0f)
                  : 0.0f;
  if (pct > 100.0f) pct = 100.0f;
  float liveFps = (m_benchmarkCollector.size() > 0)
                      ? m_benchmarkCollector.computeResults().avgFps
                      : 0.0f;
  ImGui::SetNextWindowPos(ImVec2(ImGui::GetIO().DisplaySize.x - 460.0f,
                                 ImGui::GetIO().DisplaySize.y - 60.0f));
  ImGui::SetNextWindowSize(ImVec2(450.0f, 40.0f));
  ImGui::Begin("##BenchmarkOverlay", nullptr,
               ImGuiWindowFlags_NoTitleBar | ImGuiWindowFlags_NoResize |
                   ImGuiWindowFlags_NoMove | ImGuiWindowFlags_NoScrollbar);
  char buf[256];
  std::snprintf(buf, sizeof(buf),
                "[BENCHMARK IN PROGRESS: %.0f%% | Station: %s | Frame: %d | Live FPS: %.0f]",
                pct, curId.c_str(), m_benchmarkTotalFrames, liveFps);
  ImGui::TextUnformatted(buf);
  ImGui::End();
}

void AppGL::drawPhotoDirectorOverlay() {
  if (m_photoGrid <= 0) return;
  ImDrawList* drawList = ImGui::GetBackgroundDrawList();
  const ImVec2 disp = ImGui::GetIO().DisplaySize;
  const ImU32 gridCol = IM_COL32(200, 230, 255, 75);
  const ImU32 dotCol = IM_COL32(255, 215, 64, 140);
  const ImU32 centerCol = IM_COL32(0, 255, 200, 100);

  if (m_photoGrid == 1) {
    // Rule of Thirds (3x3 grid)
    float x1 = disp.x / 3.0f;
    float x2 = 2.0f * disp.x / 3.0f;
    float y1 = disp.y / 3.0f;
    float y2 = 2.0f * disp.y / 3.0f;
    drawList->AddLine(ImVec2(x1, 0.0f), ImVec2(x1, disp.y), gridCol, 1.0f);
    drawList->AddLine(ImVec2(x2, 0.0f), ImVec2(x2, disp.y), gridCol, 1.0f);
    drawList->AddLine(ImVec2(0.0f, y1), ImVec2(disp.x, y1), gridCol, 1.0f);
    drawList->AddLine(ImVec2(0.0f, y2), ImVec2(disp.x, y2), gridCol, 1.0f);

    // Power points (intersections)
    drawList->AddCircle(ImVec2(x1, y1), 4.5f, dotCol, 12, 1.5f);
    drawList->AddCircle(ImVec2(x2, y1), 4.5f, dotCol, 12, 1.5f);
    drawList->AddCircle(ImVec2(x1, y2), 4.5f, dotCol, 12, 1.5f);
    drawList->AddCircle(ImVec2(x2, y2), 4.5f, dotCol, 12, 1.5f);
  } else if (m_photoGrid == 2) {
    // Golden Ratio (1 : 0.618 : 1) -> 0.382 and 0.618
    float x1 = disp.x * 0.382f;
    float x2 = disp.x * 0.618f;
    float y1 = disp.y * 0.382f;
    float y2 = disp.y * 0.618f;
    drawList->AddLine(ImVec2(x1, 0.0f), ImVec2(x1, disp.y), gridCol, 1.0f);
    drawList->AddLine(ImVec2(x2, 0.0f), ImVec2(x2, disp.y), gridCol, 1.0f);
    drawList->AddLine(ImVec2(0.0f, y1), ImVec2(disp.x, y1), gridCol, 1.0f);
    drawList->AddLine(ImVec2(0.0f, y2), ImVec2(disp.x, y2), gridCol, 1.0f);

    drawList->AddCircle(ImVec2(x1, y1), 5.0f, dotCol, 16, 1.5f);
    drawList->AddCircle(ImVec2(x2, y1), 5.0f, dotCol, 16, 1.5f);
    drawList->AddCircle(ImVec2(x1, y2), 5.0f, dotCol, 16, 1.5f);
    drawList->AddCircle(ImVec2(x2, y2), 5.0f, dotCol, 16, 1.5f);
  } else if (m_photoGrid == 3) {
    // Crosshair & Center Box
    float cx = disp.x * 0.5f;
    float cy = disp.y * 0.5f;
    float sz = 24.0f;
    drawList->AddLine(ImVec2(cx - sz, cy), ImVec2(cx + sz, cy), centerCol, 1.5f);
    drawList->AddLine(ImVec2(cx, cy - sz), ImVec2(cx, cy + sz), centerCol, 1.5f);
    drawList->AddCircle(ImVec2(cx, cy), sz * 0.75f, centerCol, 24, 1.2f);
  }
}

void AppGL::drawGwDetectorHud() {
  const Station* curSt = m_sceneManager->getCurrentStation();
  std::string stId = curSt ? curSt->id : "deep_space";
  std::string stName = curSt ? curSt->name : "Deep Space";

  ImGui::SetNextWindowSize(ImVec2(390.0f, 275.0f), ImGuiCond_FirstUseEver);
  if (ImGui::Begin(uiRu("Гравитационно-волновой интерферометр (GW)###GWDet",
                        "Gravitational Wave Interferometer (GW)###GWDet"),
                   &m_showGwDetector, ImGuiWindowFlags_NoCollapse)) {
    ImGui::TextColored(ImVec4(0.25f, 0.85f, 1.0f, 1.0f),
                       "%s", uiRu("СЕНСОРНЫЙ КАНАЛ ДЕТЕКТОРА LIGO / LISA",
                                  "LIGO / LISA SYNTHETIC STRAIN CHANNEL"));
    ImGui::TextColored(ImVec4(0.65f, 0.70f, 0.75f, 1.0f), "%s: %s [%s]",
                       uiRu("Источник", "Source"), stName.c_str(), stId.c_str());

    float simTime = static_cast<float>(glfwGetTime());
    float fBase = 45.0f;
    float chirpAmp = 0.85f;
    const char* eventType = "Stochastic Background";
    float snr = 8.2f;

    if (stId == "gw170817") {
      eventType = "BNS Coalescence Chirp (GW170817)";
      // Chirp sweep: frequency sweeps upwards
      float tCycle = std::fmod(simTime, 6.0f);
      fBase = 35.0f + 140.0f * (tCycle / 6.0f) * (tCycle / 6.0f);
      chirpAmp = 0.3f + 0.7f * (tCycle / 6.0f);
      snr = 32.4f;
    } else if (stId == "sgra" || stId == "m87") {
      eventType = "Supermassive BH Horizon QNM & Tidal Ringdown";
      fBase = 8.5f;
      chirpAmp = 0.95f;
      snr = 28.1f;
    } else if (stId == "sn1987a") {
      eventType = "Core-Collapse Supernova Shock Burst";
      fBase = 120.0f;
      chirpAmp = 0.75f * (0.6f + 0.4f * std::sin(simTime * 4.0f));
      snr = 19.8f;
    } else if (stId == "m1") {
      eventType = "Crab Pulsar Continuous CW (2x Spin)";
      fBase = 59.3f;
      chirpAmp = 0.65f;
      snr = 15.2f;
    }

    ImGui::TextColored(ImVec4(0.95f, 0.80f, 0.30f, 1.0f), "%s: %s",
                       uiRu("Тип сигнала", "Signal Class"), eventType);
    ImGui::Text("f_GW: %.1f Hz  |  SNR: %.1f  |  h_peak: ~10^-21", fBase, snr);

    // Oscilloscope canvas
    ImVec2 canvasPos = ImGui::GetCursorScreenPos();
    ImVec2 canvasSz = ImVec2(ImGui::GetContentRegionAvail().x, 110.0f);
    if (canvasSz.x < 50.0f) canvasSz.x = 50.0f;

    ImDrawList* dl = ImGui::GetWindowDrawList();
    dl->AddRectFilled(canvasPos, ImVec2(canvasPos.x + canvasSz.x, canvasPos.y + canvasSz.y),
                      IM_COL32(10, 16, 24, 240), 4.0f);
    dl->AddRect(canvasPos, ImVec2(canvasPos.x + canvasSz.x, canvasPos.y + canvasSz.y),
                IM_COL32(40, 80, 120, 180), 4.0f);

    // Zero line and grid ticks
    float midY = canvasPos.y + canvasSz.y * 0.5f;
    dl->AddLine(ImVec2(canvasPos.x, midY), ImVec2(canvasPos.x + canvasSz.x, midY),
                IM_COL32(60, 100, 140, 100), 1.0f);

    // Dual polarization waveform traces
    const int numSamples = 120;
    const float dt = canvasSz.x / static_cast<float>(numSamples - 1);
    const float halfH = canvasSz.y * 0.42f;

    ImVec2 prevP(canvasPos.x, midY);
    ImVec2 prevC(canvasPos.x, midY);

    for (int i = 0; i < numSamples; ++i) {
      float tSample = simTime + static_cast<float>(i) * 0.015f;
      float phase = tSample * fBase * 0.25f;
      float hp = chirpAmp * std::cos(phase);
      float hc = chirpAmp * std::sin(phase);

      ImVec2 curP(canvasPos.x + i * dt, midY - hp * halfH);
      ImVec2 curC(canvasPos.x + i * dt, midY - hc * halfH);

      if (i > 0) {
        // h+ in cyan
        dl->AddLine(prevP, curP, IM_COL32(0, 235, 255, 230), 1.8f);
        // h_cross in magenta
        dl->AddLine(prevC, curC, IM_COL32(255, 75, 180, 180), 1.4f);
      }
      prevP = curP;
      prevC = curC;
    }

    ImGui::Dummy(canvasSz);
    ImGui::TextColored(ImVec4(0.0f, 0.9f, 1.0f, 1.0f), "— h+(t) [Plus]");
    ImGui::SameLine();
    ImGui::TextColored(ImVec4(1.0f, 0.3f, 0.7f, 1.0f), "  — h_x(t) [Cross]");
    ImGui::SameLine();
    ImGui::TextColored(ImVec4(0.6f, 0.6f, 0.6f, 1.0f), "  (Strain h/h0)");
  }
  ImGui::End();
}

void AppGL::drawSpectrometer() {
  const Station* curSt = m_sceneManager->getCurrentStation();
  std::string stId = curSt ? curSt->id : "sol";
  m_missions.onSpectroscopyScan(stId);

  // Compute beta from speedK
  const double beta = static_cast<double>(m_speedK) * 0.40;
  SpectralAnalysis sp = analyzeSpectrum(stId, beta);

  ImGui::SetNextWindowSize(ImVec2(520.0f, 480.0f), ImGuiCond_FirstUseEver);
  const bool pushed = modernPushFont();
  if (ImGui::Begin(uiRu("Астрофизический спектрометр (C)###Spectrometer",
                        "Astrophysical Spectrometer (C)###Spectrometer"),
                   &m_spectrometerOpen)) {
    // Header
    ImGui::TextColored(ImVec4(0.25f, 0.85f, 1.0f, 1.0f), "%s: %s",
                       uiRu("ОБЪЕКТ СКАНИРОВАНИЯ", "SCAN TARGET"), sp.targetName.c_str());
    ImGui::TextColored(ImVec4(0.95f, 0.80f, 0.30f, 1.0f), "%s: %s",
                       uiRu("Спектральный класс", "Spectral Class"), sp.spectralClass.c_str());

    ImGui::Text("T_eff: %.0f K  |  B: %.2e T  |  %s: %s",
                sp.surfaceTempK, sp.magneticFieldTesla,
                uiRu("Радиация", "Radiation"), sp.radiationLevel.c_str());

    if (sp.hasBiosignature) {
      ImGui::TextColored(ImVec4(0.2f, 0.95f, 0.4f, 1.0f), "☘ %s",
                         uiRu("БИОСИГНАТУРА ОБНАРУЖЕНА (CH4, H2O, O2)",
                              "BIOSPHERE SIGNATURE CONFIRMED (CH4, H2O, O2)"));
    } else {
      ImGui::TextColored(ImVec4(0.6f, 0.65f, 0.7f, 1.0f), "— %s",
                         uiRu("Органических биосигнатур не обнаружено",
                              "No organic biosignatures detected"));
    }

    ImGui::Separator();

    // Doppler information
    const double dopplerFactor = std::sqrt((1.0 + beta) / (1.0 - beta));
    if (std::abs(beta) > 0.01) {
      ImGui::TextColored(ImVec4(0.4f, 0.8f, 1.0f, 1.0f),
                         "β = %.2f c | D_Doppler = %.3f (%s)",
                         beta, dopplerFactor,
                         beta > 0 ? uiRu("Синее смещение", "Blue-shift")
                                  : uiRu("Красное смещение", "Red-shift"));
    } else {
      ImGui::TextColored(ImVec4(0.6f, 0.65f, 0.7f, 1.0f),
                         "β ≈ 0.00 c | D_Doppler = 1.000 (%s)",
                         uiRu("Лабораторная система отсчёта", "Rest Frame"));
    }

    // Rainbow spectrum dispersion canvas
    ImVec2 canvasPos = ImGui::GetCursorScreenPos();
    ImVec2 canvasSz = ImVec2(ImGui::GetContentRegionAvail().x, 60.0f);
    if (canvasSz.x < 100.0f) canvasSz.x = 100.0f;
    ImDrawList* dl = ImGui::GetWindowDrawList();

    // Background
    dl->AddRectFilled(canvasPos, ImVec2(canvasPos.x + canvasSz.x, canvasPos.y + canvasSz.y),
                      IM_COL32(10, 10, 15, 255), 4.0f);

    // Draw rainbow dispersion segments from 380nm to 750nm
    const float minNm = 380.0f;
    const float maxNm = 750.0f;
    const int segments = 60;
    const float segW = canvasSz.x / static_cast<float>(segments);

    for (int s = 0; s < segments; ++s) {
      float t = static_cast<float>(s) / static_cast<float>(segments);
      float nm = minNm + t * (maxNm - minNm);
      float r = 0.0f, g = 0.0f, b = 0.0f;
      if (nm >= 380.0f && nm < 440.0f) {
        r = -(nm - 440.0f) / (440.0f - 380.0f);
        b = 1.0f;
      } else if (nm >= 440.0f && nm < 490.0f) {
        g = (nm - 440.0f) / (490.0f - 440.0f);
        b = 1.0f;
      } else if (nm >= 490.0f && nm < 510.0f) {
        g = 1.0f;
        b = -(nm - 510.0f) / (510.0f - 490.0f);
      } else if (nm >= 510.0f && nm < 580.0f) {
        r = (nm - 510.0f) / (580.0f - 510.0f);
        g = 1.0f;
      } else if (nm >= 580.0f && nm < 645.0f) {
        r = 1.0f;
        g = -(nm - 645.0f) / (645.0f - 580.0f);
      } else if (nm >= 645.0f && nm <= 750.0f) {
        r = 1.0f;
      }
      ImU32 col = IM_COL32(static_cast<int>(r * 220), static_cast<int>(g * 220),
                           static_cast<int>(b * 220), 220);
      dl->AddRectFilled(ImVec2(canvasPos.x + s * segW, canvasPos.y),
                        ImVec2(canvasPos.x + (s + 1) * segW + 1.0f, canvasPos.y + canvasSz.y),
                        col);
    }

    // Overlay spectral lines
    for (const auto& line : sp.lines) {
      if (line.wavelengthNm >= minNm && line.wavelengthNm <= maxNm) {
        float xNorm = (line.wavelengthNm - minNm) / (maxNm - minNm);
        float lineX = canvasPos.x + xNorm * canvasSz.x;
        if (line.isEmission) {
          dl->AddLine(ImVec2(lineX, canvasPos.y), ImVec2(lineX, canvasPos.y + canvasSz.y),
                      IM_COL32(255, 255, 255, 255), 2.5f);
          dl->AddLine(ImVec2(lineX, canvasPos.y), ImVec2(lineX, canvasPos.y + canvasSz.y),
                      IM_COL32(120, 240, 255, 180), 4.5f);
        } else {
          dl->AddLine(ImVec2(lineX, canvasPos.y), ImVec2(lineX, canvasPos.y + canvasSz.y),
                      IM_COL32(12, 12, 18, 245), 2.2f);
        }
      }
    }

    // Border
    dl->AddRect(canvasPos, ImVec2(canvasPos.x + canvasSz.x, canvasPos.y + canvasSz.y),
                IM_COL32(80, 140, 200, 200), 4.0f, 0, 1.5f);
    ImGui::Dummy(canvasSz);

    // Spectrum labels
    ImGui::TextColored(ImVec4(0.5f, 0.6f, 0.7f, 1.0f), "380 nm [UV/Violet]");
    ImGui::SameLine(canvasSz.x * 0.45f);
    ImGui::TextColored(ImVec4(0.5f, 0.9f, 0.5f, 1.0f), "550 nm [Green]");
    ImGui::SameLine(canvasSz.x - 110.0f);
    ImGui::TextColored(ImVec4(0.9f, 0.5f, 0.5f, 1.0f), "750 nm [NIR/Red]");

    ImGui::Spacing();
    ImGui::TextColored(ImVec4(0.85f, 0.85f, 0.9f, 1.0f), "%s:",
                       uiRu("Химический состав и спектральные линии", "Chemical Abundance & Spectral Lines"));
    for (const auto& [elem, pct] : sp.chemicalAbundance) {
      char buf[64];
      std::snprintf(buf, sizeof(buf), "%.2f%%", pct);
      ImGui::ProgressBar(pct / 100.0f, ImVec2(-1, 14.0f), buf);
      ImGui::SameLine(10.0f);
      ImGui::Text("%s", elem.c_str());
    }

    ImGui::Spacing();
    ImGui::TextWrapped("%s", uiRu(sp.summaryRu.c_str(), sp.summaryEn.c_str()));
    ImGui::Spacing();
    ImGui::Separator();

    // Log to Codex button
    bool scanned = m_codex.isScanned(stId);
    if (scanned) {
      ImGui::BeginDisabled();
      ImGui::Button(uiRu("✓ Уже занесено в Кодекс открытий (+100 RP)",
                         "✓ Already Logged in Ship Codex (+100 RP)"), ImVec2(-1, 28.0f));
      ImGui::EndDisabled();
    } else {
      if (ImGui::Button(uiRu("✦ Занести в Кодекс открытий (+100 RP)",
                            "✦ Log to Ship Codex (+100 RP)"), ImVec2(-1, 28.0f))) {
        double now = glfwGetTime();
        if (m_codex.scanObject(stId, now, colonyResearchBonus(m_colonyStages))) {
          m_audio.playChime();
          RadioMessage rm;
          rm.id = "scan_" + stId;
          rm.callsignRu = "Елена Ростова [Астрофизик]";
          rm.callsignEn = "Elena Rostova [Astrophysicist]";
          rm.textRu = "Спектральный анализ " + sp.targetName + " зарегистрирован в бортовой Кодекс! Получено +100 очков исследований (RP).";
          rm.textEn = "Spectral breakdown of " + sp.targetName + " logged into the Ship Codex! +100 Research Points (RP) acquired.";
          rm.durationSec = 6.0;
          rm.priority = 1.5f;
          m_bridgeComms.queueMessage(rm, now);
          saveProfileNow(false);
        }
      }
    }
  }
  ImGui::End();
  if (pushed) ImGui::PopFont();
}

bool AppGL::foundColony(const std::string& id) {
  if (!colonyWorld(id) || colonyStage(m_colonyStages, id) != 0) return false;
  const Station* current = m_sceneManager->getCurrentStation();
  if (!current) return false;
  bool nearby = false;
  for (const auto& site : m_sceneManager->colonySites()) {
    if (site.id != id || site.stationId != current->id) continue;
    const Vec3 delta = m_camera.position - site.pos;
    const double limit = site.radius * 8.0 + 2.5;
    nearby = delta.x * delta.x + delta.y * delta.y + delta.z * delta.z <= limit * limit;
  }
  if (!nearby) return false;
  m_colonies.push_back(id);
  m_colonyStages[id] = 1;
  m_sceneManager->setColonies(m_colonies);
  m_sceneManager->setColonyStages(m_colonyStages);
  checkAchievements();
  saveProfileNow(true);
  return true;
}

bool AppGL::upgradeColony(const std::string& id) {
  const int stageBefore = colonyStage(m_colonyStages, id);
  int points = m_codex.getTotalResearchPoints();
  const int before = points;
  if (advanceColony(m_colonyStages, id, m_codex.getScannedCount(), points) != ColonyUpgradeResult::Success)
    return false;
  m_codex.spendResearchPoints(before - points);
  m_sceneManager->setColonyStages(m_colonyStages);

  // World-development milestones pay out once the stage crosses them.
  const int stage = colonyStage(m_colonyStages, id);
  const int reward = colonyMilestoneReward(stageBefore, stage);
  if (reward > 0) {
    std::string lastRu, lastEn;
    for (const auto& m : colonyTerraformMilestones()) {
      if (m.stage <= stageBefore || m.stage > stage) continue;
      lastRu = m.nameRu;
      lastEn = m.nameEn;
    }
    m_codex.addResearchPoints(reward);
    m_crew.gainXp(CrewPost::ScienceOfficer, 30);
    m_crew.gainXp(CrewPost::ChiefEngineer, 15);
    float atmo = 0.0f, bio = 0.0f;
    colonyTerraformState(stage, atmo, bio);
    Toast mt;
    mt.title = uiRu("Освоение мира", "World development");
    char body[256];
    std::snprintf(body, sizeof(body),
                  uiRu("%s — +%d RP. Атмосфера %.0f%%, биосфера %.0f%%",
                       "%s — +%d RP. Atmosphere %.0f%%, biosphere %.0f%%"),
                  uiRu(lastRu.c_str(), lastEn.c_str()), reward, atmo * 100.0f, bio * 100.0f);
    mt.desc = body;
    mt.time = static_cast<float>(glfwGetTime());
    m_toasts.push_back(mt);
    m_audio.playChime();
  }
  applyColonyArchiveReveal();
  saveProfileNow(true);
  return true;
}

void AppGL::applyColonyArchiveReveal() {
  if (!colonyRevealsHiddenHypotheses(m_colonyStages)) return;
  const int revealed = m_zettelkasten.revealHiddenHypotheses();
  if (revealed <= 0) return;
  Toast t;
  t.title = uiRu("Архив рассекречен", "Archive declassified");
  char body[96];
  std::snprintf(body, sizeof(body),
                uiRu("Снято грифов: %d", "Classified dossiers opened: %d"), revealed);
  t.desc = body;
  t.time = static_cast<float>(glfwGetTime());
  m_toasts.push_back(t);
}

void AppGL::updateColonyEconomy(float dt) {
  (void)dt;
  const double now = glfwGetTime();
  // Deflector capacity follows the shield perk of the best developed world, so
  // the same radiation drain leaves margin instead of a quicker death.
  m_shieldMax = ship::shieldCapacity(colonyShieldBoost(m_colonyStages));
  if (m_lastPassiveColonyTime == 0.0) {
    m_lastPassiveColonyTime = now;
  }
  // Passive RP accrual every 10 seconds
  if (now - m_lastPassiveColonyTime >= 10.0) {
    const double elapsed = now - m_lastPassiveColonyTime;
    m_lastPassiveColonyTime = now;
    const int ratePerMin = colonyPassiveRatePerMin(m_colonyStages);
    if (ratePerMin > 0) {
      const float sciBonus = m_crew.scienceYieldMultiplier();
      const int addPoints = static_cast<int>(std::round(ratePerMin * (elapsed / 60.0) * sciBonus));
      if (addPoints > 0) {
        m_codex.addResearchPoints(addPoints);
      }
    }
  }

  // Ship resupply (refuel and shield recharge) near spaceports (stage >= 14)
  if (m_sceneManager) {
    const Station* current = m_sceneManager->getCurrentStation();
    for (const auto& site : m_sceneManager->colonySites()) {
      if (!current || site.stationId != current->id) continue;
      if (!colonyCanResupply(m_colonyStages, site.id)) continue;
      const Vec3 d = m_camera.position - site.pos;
      const double limit = site.radius * 8.0 + 3.0;
      if (d.x * d.x + d.y * d.y + d.z * d.z <= limit * limit) {
        // In spaceport service zone: resupply fuel & recharge shield & repair hull
        if (m_ship.fuel < 100.0f) {
          m_ship.fuel = std::min(100.0f, m_ship.fuel + 15.0f * dt);
        }
        if (m_ship.shield < m_shieldMax) {
          m_ship.shield = std::min(m_shieldMax, m_ship.shield + 20.0f * m_crew.shieldRegenMultiplier() * dt);
        }
        if (m_ship.hull < 100.0f) {
          m_ship.hull = std::min(100.0f, m_ship.hull + 5.0f * dt);
        }
      }
    }
  }
}

void AppGL::drawColonies() {
  const bool pushed = modernPushFont();
  const ImVec2 display = ImGui::GetIO().DisplaySize;
  ImGui::SetNextWindowPos(ImVec2(display.x * 0.5f, display.y * 0.5f), ImGuiCond_FirstUseEver, ImVec2(0.5f, 0.5f));
  ImGui::SetNextWindowSize(ImVec2(std::min(980.0f, display.x - 30.0f), std::min(780.0f, display.y - 30.0f)), ImGuiCond_FirstUseEver);
  if (ImGui::Begin(uiRu("Планетарные Цивилизации & Инфраструктура###colonies", "Planetary Civilizations & Infrastructure###colonies"), &m_coloniesOpen)) {
    const ColonyWorld* selected = colonyWorld(m_selectedColony);
    if (!selected) selected = colonyWorld("mars");

    // World selector combo
    ImGui::SetNextItemWidth(-1);
    if (ImGui::BeginCombo("##colonyWorld", uiRu(selected->nameRu, selected->nameEn))) {
      for (const auto& world : colonyWorlds()) {
        const int wStage = colonyStage(m_colonyStages, world.id);
        char label[128];
        if (wStage > 0) {
          std::snprintf(label, sizeof(label), "%s  [%s: %d/24 | %s]",
                        uiRu(world.nameRu, world.nameEn),
                        uiRu("Этап", "Stage"), wStage,
                        uiRu(colonyEpochNameRu(colonyEpoch(wStage)), colonyEpochNameEn(colonyEpoch(wStage))));
        } else {
          std::snprintf(label, sizeof(label), "%s  [%s]",
                        uiRu(world.nameRu, world.nameEn),
                        uiRu("Не колонизирована", "Uncolonized"));
        }
        if (ImGui::Selectable(label, m_selectedColony == world.id))
          m_selectedColony = world.id;
      }
      ImGui::EndCombo();
    }
    const int stage = colonyStage(m_colonyStages, m_selectedColony);
    const auto& stages = colonyStages();
    const ColonyEpoch epoch = colonyEpoch(stage);

    // Color theme based on epoch
    ImVec4 epochColor(0.2f, 0.85f, 1.0f, 1.0f);
    if (epoch == ColonyEpoch::Industry) epochColor = ImVec4(1.0f, 0.75f, 0.25f, 1.0f);
    else if (epoch == ColonyEpoch::Society) epochColor = ImVec4(0.35f, 1.0f, 0.60f, 1.0f);
    else if (epoch == ColonyEpoch::HighTech) epochColor = ImVec4(0.85f, 0.50f, 1.0f, 1.0f);
    else if (epoch == ColonyEpoch::Civilization) epochColor = ImVec4(1.0f, 0.90f, 0.35f, 1.0f);

    // Planetary Environment & Telemetry Bar
    ImGui::PushStyleColor(ImGuiCol_ChildBg, ImVec4(0.05f, 0.08f, 0.12f, 0.85f));
    ImGui::BeginChild("##worldEnvBar", ImVec2(0.0f, 68.0f), true);
    ImGui::TextColored(epochColor, "✦ %s: %s   |   %s: %s",
                       uiRu("Мир", "World"), uiRu(selected->nameRu, selected->nameEn),
                       uiRu("Эпоха", "Epoch"), uiRu(colonyEpochNameRu(epoch), colonyEpochNameEn(epoch)));
    ImGui::TextColored(ImVec4(0.80f, 0.85f, 0.90f, 1.0f),
                       "%s: %s   |   %s: %s   |   %s: %s",
                       uiRu("Гравитация", "Gravity"), selected->gravity,
                       uiRu("Атмосфера", "Atmosphere"), uiRu(selected->atmosphereRu, selected->atmosphereEn),
                       uiRu("Температура", "Temperature"), uiRu(selected->temperatureRu, selected->temperatureEn));
    ImGui::TextColored(ImVec4(0.40f, 0.95f, 1.0f, 1.0f), "★ %s: %s — %s",
                       uiRu("Перк планеты", "World perk"),
                       uiRu(selected->perk.titleRu, selected->perk.titleEn),
                       uiRu(selected->perk.descriptionRu, selected->perk.descriptionEn));
    ImGui::EndChild();
    ImGui::PopStyleColor();

    // Civilization telemetry row
    ImGui::Spacing();
    ImGui::Text("%s: %d RP   |   %s: %d   |   %s: +%d%%   |   %s: %d   |   %s: +%d RP/%s",
                uiRu("Баланс RP", "Balance RP"), m_codex.getTotalResearchPoints(),
                uiRu("Открытия", "Discoveries"), m_codex.getScannedCount(),
                uiRu("Бонус науки", "Science bonus"), colonyResearchBonus(m_colonyStages),
                uiRu("Население Федерации", "Civilization pop"), colonyTotalPopulation(m_colonyStages),
                uiRu("Пассивный доход", "Passive rate"), colonyPassiveRatePerMin(m_colonyStages),
                uiRu("мин", "min"));

    // Что перки сети колоний делают симуляции прямо сейчас, а не только в тексте.
    {
      char perkBuf[256];
      std::snprintf(perkBuf, sizeof(perkBuf),
                    uiRu("Перки в симуляции: перезарядка варпа -%.0f%%, ёмкость щита +%.0f%%, %s, %s, %s",
                         "Perks in sim: warp recharge -%.0f%%, shield capacity +%.0f%%, %s, %s, %s"),
                    colonyWarpRechargeBoost(m_colonyStages) * 100.0f,
                    colonyShieldBoost(m_colonyStages) * 100.0f,
                    uiRu(colonyUnlocksEliteContracts(m_colonyStages) ? "элитные контракты" : "без элиты",
                         colonyUnlocksEliteContracts(m_colonyStages) ? "elite contracts" : "no elite"),
                    uiRu(colonyRevealsHiddenHypotheses(m_colonyStages) ? "архив рассекречен" : "архив закрыт",
                         colonyRevealsHiddenHypotheses(m_colonyStages) ? "archive open" : "archive sealed"),
                    uiRu(colonyUnlocksGalacticVector(m_colonyStages) ? "вектор на M13" : "вектор закрыт",
                         colonyUnlocksGalacticVector(m_colonyStages) ? "M13 vector" : "vector sealed"));
      ImGui::TextColored(ImVec4(0.62f, 0.95f, 0.72f, 1.0f), "* %s", perkBuf);
    }

    ImGui::Spacing();
    if (ImGui::BeginTabBar("##colonyMainTabs")) {
      if (ImGui::BeginTabItem(uiRu("🏗 Инфраструктура & Проекты", "🏗 Infrastructure & Projects"))) {
        m_colonyTab = 0;

        // Progress bar across the 24 stages
        ImGui::Spacing();
        char progressBuf[128];
        std::snprintf(progressBuf, sizeof(progressBuf), "%s: %d / %d (%s)",
                      uiRu("Прогресс цивилизации", "Civilization progress"),
                      stage, kColonyStageCount,
                      uiRu(colonyEpochNameRu(epoch), colonyEpochNameEn(epoch)));
        ImGui::ProgressBar(static_cast<float>(stage) / kColonyStageCount, ImVec2(-1, 24), progressBuf);

    // What actually stands on the surface right now, and which power plant the
    // world runs on (fission / hydro / thermal depending on the body).
    if (stage > 0) {
      const auto buildPlan = colonyBuildPlan(m_selectedColony, stage);
      ImGui::Spacing();
      ImGui::TextColored(ImVec4(0.72f, 0.86f, 1.0f, 1.0f), "%s (%s): %d",
                         uiRu("Построено объектов", "Built structures"),
                         uiRu(selected->nameRu, selected->nameEn),
                         colonyStructureCount(m_selectedColony, stage));
      ImGui::SameLine();
      const char* power = colonyEnergyAsset(m_selectedColony);
      ImGui::TextColored(ImVec4(0.95f, 0.78f, 0.35f, 1.0f), "| %s: %s",
                         uiRu("Энергетика", "Power base"),
                         std::string(power) == "nuclear"
                             ? uiRu("АЭС (гиперболоидные градирни)", "Nuclear plant (hyperboloid towers)")
                             : std::string(power) == "hydro"
                                   ? uiRu("ГЭС (дамба и водосброс)", "Hydro station (dam and spillway)")
                                   : uiRu("ГРЭС (котлооборот и градирни воздуха)",
                                          "Condensing station (boiler house and ACC)"));
      static const struct { const char* key; const char* ru; const char* en; } kAssetNames[] = {
          {"dome", "купола", "domes"}, {"factory", "заводы", "plants"},
          {"pad", "площадки", "pads"}, {"datacenter", "дата-центры", "data campuses"},
          {"nuclear", "АЭС", "nuclear plants"}, {"hydro", "ГЭС", "hydro stations"},
          {"thermal", "ГРЭС", "condensing stations"}};
      std::string summary;
      for (const auto& entry : buildPlan) {
        for (const auto& named : kAssetNames) {
          if (entry.first == named.key) {
            if (!summary.empty()) summary += ", ";
            summary += std::to_string(entry.second) + " " + uiRu(named.ru, named.en);
            break;
          }
        }
      }
      if (!summary.empty()) ImGui::TextWrapped("  %s", summary.c_str());

      // Terraforming ladder: elements -> atmosphere -> organics -> life.
      float atmo = 0.0f, bio = 0.0f;
      colonyTerraformState(stage, atmo, bio);
      ImGui::Spacing();
      ImGui::TextColored(ImVec4(0.55f, 0.95f, 0.75f, 1.0f), "%s: %s %.0f%% | %s %.0f%%",
                         uiRu("Освоение мира", "World development"),
                         uiRu("атмосфера", "atmosphere"), atmo * 100.0f,
                         uiRu("биосфера", "biosphere"), bio * 100.0f);
      ImGui::ProgressBar(atmo, ImVec2(-1, 16), uiRu("Атмосфера", "Atmosphere"));
      ImGui::ProgressBar(bio, ImVec2(-1, 16), uiRu("Биосфера", "Biosphere"));
      for (const auto& m : colonyTerraformMilestones()) {
        const bool reached = stage >= m.stage;
        ImGui::PushStyleColor(ImGuiCol_Text,
                              reached ? ImVec4(0.45f, 1.0f, 0.62f, 1.0f)
                                      : ImVec4(0.55f, 0.60f, 0.70f, 0.85f));
        ImGui::Text("%s  %s", reached ? "[+]" : "[ ]", uiRu(m.nameRu, m.nameEn));
        ImGui::PopStyleColor();
        if (reached) {
          ImGui::PushStyleColor(ImGuiCol_Text, ImVec4(0.62f, 0.72f, 0.82f, 0.9f));
          ImGui::TextWrapped("    %s", uiRu(m.detailRu, m.detailEn));
          ImGui::PopStyleColor();
        }
      }
    }

    // Active project / Next project construction box
    ImGui::Spacing();
    if (stage == 0) {
      bool nearby = false;
      const Station* current = m_sceneManager->getCurrentStation();
      for (const auto& site : m_sceneManager->colonySites()) {
        if (!current || site.stationId != current->id || site.id != m_selectedColony) continue;
        const Vec3 d = m_camera.position - site.pos;
        const double limit = site.radius * 8.0 + 2.5;
        nearby = d.x * d.x + d.y * d.y + d.z * d.z <= limit * limit;
      }
      ImGui::PushStyleColor(ImGuiCol_ChildBg, ImVec4(0.08f, 0.12f, 0.08f, 0.85f));
      ImGui::BeginChild("##foundPrompt", ImVec2(0.0f, 110.0f), true);
      ImGui::TextColored(ImVec4(0.35f, 1.0f, 0.55f, 1.0f), "❖ %s",
                         uiRu("Готовность к Первичному Десанту", "Ready for Initial Touchdown"));
      ImGui::TextWrapped("%s", uiRu("Для основания цивилизации на этом мире подлетите к планете на расстояние посадочной орбиты. Первый разведывательный аванпост бесплатен.",
                                   "To establish human civilization on this world, enter close orbital radius. The initial survey outpost is free of charge."));
      ImGui::Spacing();
      ImGui::BeginDisabled(!nearby);
      if (ImGui::Button(uiRu("✦ Развернуть Первичный Аванпост (Бесплатно)", "✦ Deploy Survey Outpost (Free)"), ImVec2(-1, 32))) {
        foundColony(m_selectedColony);
      }
      ImGui::EndDisabled();
      if (!nearby) {
        ImGui::TextColored(ImVec4(1.0f, 0.6f, 0.2f, 1.0f), "%s",
                           uiRu("Подлетите ближе к небесному телу для разблокировки десанта.",
                                "Fly closer to the celestial body to enable landing deployment."));
      }
      ImGui::EndChild();
      ImGui::PopStyleColor();
    } else if (stage < kColonyStageCount) {
      const auto& next = stages[stage];
      const int cost = colonyUpgradeCost(m_colonyStages, m_selectedColony, stage);
      const bool funded = m_codex.getTotalResearchPoints() >= cost;
      const bool researched = m_codex.getScannedCount() >= next.requiredScans;

      ImGui::PushStyleColor(ImGuiCol_ChildBg, ImVec4(0.06f, 0.10f, 0.16f, 0.85f));
      ImGui::BeginChild("##nextStageBox", ImVec2(0.0f, 160.0f), true);
      ImGui::TextColored(ImVec4(0.35f, 0.90f, 1.0f, 1.0f), "✦ %s %d: %s (%s)",
                         uiRu("Следующий Проект", "Next Project"), stage + 1,
                         uiRu(next.nameRu, next.nameEn),
                         uiRu(colonyEpochNameRu(next.epoch), colonyEpochNameEn(next.epoch)));
      ImGui::TextColored(ImVec4(0.75f, 0.85f, 0.95f, 1.0f), "%s: %s",
                         uiRu("Инфраструктура", "Infrastructure"), uiRu(next.infrastructureRu, next.infrastructureEn));
      ImGui::TextWrapped("%s: %s", uiRu("Научный базис", "Scientific basis"), uiRu(next.loreRu, next.loreEn));
      ImGui::TextColored(ImVec4(0.40f, 1.0f, 0.65f, 1.0f), "★ %s: %s",
                         uiRu("Открытия & Бонусы", "Tech Unlocks & Perks"), uiRu(next.techUnlocksRu, next.techUnlocksEn));
      ImGui::Spacing();
      ImGui::Text("%s: %d RP   |   %s: %d / %d   |   %s: +%d чел.",
                  uiRu("Стоимость", "Cost"), cost,
                  uiRu("Требуемые сканы", "Required scans"), m_codex.getScannedCount(), next.requiredScans,
                  uiRu("Прирост населения", "Population delta"), next.population - stages[stage - 1].population);
      ImGui::Spacing();
      ImGui::BeginDisabled(!funded || !researched);
      char buildBtnLabel[128];
      std::snprintf(buildBtnLabel, sizeof(buildBtnLabel), "%s (%d RP)###buildStageBtn",
                    uiRu("✦ Построить следующий этап", "✦ Build Next Stage"), cost);
      if (ImGui::Button(buildBtnLabel, ImVec2(-1, 32))) {
        upgradeColony(m_selectedColony);
      }
      ImGui::EndDisabled();
      if (!funded || !researched) {
        ImGui::TextColored(ImVec4(1.0f, 0.65f, 0.25f, 1.0f), "%s",
                           !researched ? uiRu("Недостаточно открытий: исследуйте новые космические объекты.",
                                              "More discoveries needed: scan new astronomical objects.")
                                       : uiRu("Недостаточно RP: дождитесь пассивного дохода колоний или соберите образцы.",
                                              "Insufficient RP: wait for passive colony income or collect surface samples."));
      }
      ImGui::EndChild();
      ImGui::PopStyleColor();
    } else {
      ImGui::PushStyleColor(ImGuiCol_ChildBg, ImVec4(0.12f, 0.10f, 0.04f, 0.85f));
      ImGui::BeginChild("##maxStageBox", ImVec2(0.0f, 90.0f), true);
      ImGui::TextColored(ImVec4(1.0f, 0.85f, 0.25f, 1.0f), "👑 %s",
                         uiRu("Триумф Планетарной Цивилизации (Кардашев I+)",
                              "Planetary Civilization Triumph (Kardashev I+)"));
      ImGui::TextWrapped("%s", uiRu("Мир достиг абсолютного технологического могущества. Атмосферные процессоры контролируют биосферу, геомагнитный щит защищает от радиации, а квантовый маяк связывает систему со скоплением М13.",
                                   "This world has attained absolute technological mastery. Atmospheric processors regulate the biosphere, planetary magnetosphere shields from radiation, and subspace beacon connects to the M13 cluster."));
      ImGui::EndChild();
      ImGui::PopStyleColor();
    }

    // Scrollable catalog of all 24 stages grouped by Epoch
    ImGui::Separator();
    ImGui::TextColored(ImVec4(0.70f, 0.85f, 1.0f, 1.0f), "❖ %s",
                       uiRu("Генеральный План Развития Планетарной Цивилизации (24 Этапа)",
                            "Planetary Civilization Master Blueprint (24 Stages)"));
    ImGui::BeginChild("##colonyStagesScroll", ImVec2(0, 0), true);

    ColonyEpoch currentEpochGroup = static_cast<ColonyEpoch>(-1);
    for (int i = 0; i < kColonyStageCount; ++i) {
      const auto& s = stages[i];
      if (s.epoch != currentEpochGroup) {
        currentEpochGroup = s.epoch;
        ImGui::Spacing();
        ImVec4 epHdrCol(0.2f, 0.85f, 1.0f, 1.0f);
        if (currentEpochGroup == ColonyEpoch::Industry) epHdrCol = ImVec4(1.0f, 0.75f, 0.25f, 1.0f);
        else if (currentEpochGroup == ColonyEpoch::Society) epHdrCol = ImVec4(0.35f, 1.0f, 0.60f, 1.0f);
        else if (currentEpochGroup == ColonyEpoch::HighTech) epHdrCol = ImVec4(0.85f, 0.50f, 1.0f, 1.0f);
        else if (currentEpochGroup == ColonyEpoch::Civilization) epHdrCol = ImVec4(1.0f, 0.90f, 0.35f, 1.0f);

        ImGui::TextColored(epHdrCol, "═══════════ %s ═══════════",
                           uiRu(colonyEpochNameRu(currentEpochGroup), colonyEpochNameEn(currentEpochGroup)));
      }

      const bool isBuilt = (i < stage);
      const bool isNext = (i == stage);
      const ImVec4 stateColor = isBuilt ? ImVec4(0.35f, 1.0f, 0.55f, 1.0f)
                                       : (isNext ? ImVec4(1.0f, 0.85f, 0.35f, 1.0f)
                                                 : ImVec4(0.55f, 0.60f, 0.65f, 1.0f));
      const char* stateText = isBuilt ? uiRu("✓ ПОСТРОЕНО", "✓ BUILT")
                                     : (isNext ? uiRu("▶ АКТИВНЫЙ ПРОЕКТ", "▶ ACTIVE PROJECT")
                                               : uiRu("🔒 ЗАБЛОКИРОВАНО", "🔒 LOCKED"));

      ImGui::TextColored(stateColor, "[%s] %02d. %s", stateText, i + 1, uiRu(s.nameRu, s.nameEn));
      ImGui::TextColored(ImVec4(0.85f, 0.85f, 0.85f, 1.0f), "   • %s: %s",
                         uiRu("Инфраструктура", "Infrastructure"), uiRu(s.infrastructureRu, s.infrastructureEn));
      ImGui::TextColored(ImVec4(0.70f, 0.75f, 0.80f, 1.0f), "   • %s: %s",
                         uiRu("Базис", "Basis"), uiRu(s.loreRu, s.loreEn));
      ImGui::TextColored(ImVec4(0.40f, 0.90f, 0.80f, 1.0f), "   • %s: %s",
                         uiRu("Эффект", "Unlocks"), uiRu(s.techUnlocksRu, s.techUnlocksEn));
      ImGui::TextColored(ImVec4(0.60f, 0.65f, 0.70f, 1.0f),
                         "   • %s: %d чел.  |  %s: %d RP  |  %s: %d  |  %s: +%d RP/мин%s",
                         uiRu("Жителей", "Pop"), s.population,
                         uiRu("Цена", "Cost"), s.costRP,
                         uiRu("Сканы", "Scans"), s.requiredScans,
                         uiRu("Доход", "Passive"), s.passiveRpPerMin,
                         s.allowsResupply ? uiRu("  [КОСМОПОРТ]", "  [SPACEPORT]") : "");
      ImGui::Spacing();
    }
    ImGui::EndChild();
    ImGui::EndTabItem();
  }

  if (ImGui::BeginTabItem(uiRu("👥 Население & Кадры", "👥 Population & Roster"))) {
    m_colonyTab = 1;
    const auto buildPlan = (stage > 0) ? colonyBuildPlan(m_selectedColony, stage) : std::vector<std::pair<std::string, int>>{};
    const ColonyVitals vitals = calculateColonyVitals(m_selectedColony, stage, buildPlan);

    if (stage == 0) {
      ImGui::PushStyleColor(ImGuiCol_ChildBg, ImVec4(0.08f, 0.10f, 0.14f, 0.85f));
      ImGui::BeginChild("##uncolonizedPopChild", ImVec2(0.0f, 120.0f), true);
      ImGui::TextColored(ImVec4(1.0f, 0.75f, 0.25f, 1.0f), "❖ %s",
                         uiRu("Мир пока необитаем", "World is currently uninhabited"));
      ImGui::TextWrapped("%s",
                         uiRu("На этом небесном теле ещё не основан аванпост. Перейдите во вкладку 'Инфраструктура' и подлетите к планете на посадочную орбиту, чтобы основать первую колонию и привлечь поселенцев.",
                              "No outpost has been established on this celestial body. Switch to the 'Infrastructure' tab and enter close orbital radius to deploy the initial outpost and attract colonists."));
      ImGui::EndChild();
      ImGui::PopStyleColor();
    } else {
      // Demographics & Vitals Header
      const int curPop = colonyStages()[stage - 1].population;
      ImGui::PushStyleColor(ImGuiCol_ChildBg, ImVec4(0.06f, 0.09f, 0.14f, 0.85f));
      ImGui::BeginChild("##vitalsOverview", ImVec2(0.0f, 96.0f), true);

      ImGui::TextColored(ImVec4(0.35f, 0.90f, 1.0f, 1.0f), "✦ %s: %s   |   %s: %d %s",
                         uiRu("Колония", "Colony"), uiRu(selected->nameRu, selected->nameEn),
                         uiRu("Население", "Population"), curPop, uiRu("чел.", "citizens"));

      // 4 Vitals Progress Bars (Health, Nourishment, Morale, Competency)
      const float barW = (ImGui::GetContentRegionAvail().x - 30.0f) * 0.25f;
      char vBuf[64];

      ImGui::BeginGroup();
      std::snprintf(vBuf, sizeof(vBuf), "%s: %.0f%%", uiRu("Здоровье", "Health"), vitals.avgHealth);
      ImGui::ProgressBar(vitals.avgHealth * 0.01f, ImVec2(barW, 16.0f), vBuf);
      ImGui::EndGroup();

      ImGui::SameLine();
      ImGui::BeginGroup();
      std::snprintf(vBuf, sizeof(vBuf), "%s: %.0f%%", uiRu("Питание", "Nourishment"), vitals.avgNourishment);
      ImGui::ProgressBar(vitals.avgNourishment * 0.01f, ImVec2(barW, 16.0f), vBuf);
      ImGui::EndGroup();

      ImGui::SameLine();
      ImGui::BeginGroup();
      std::snprintf(vBuf, sizeof(vBuf), "%s: %.0f%%", uiRu("Мораль", "Morale"), vitals.avgMorale);
      ImGui::ProgressBar(vitals.avgMorale * 0.01f, ImVec2(barW, 16.0f), vBuf);
      ImGui::EndGroup();

      ImGui::SameLine();
      ImGui::BeginGroup();
      std::snprintf(vBuf, sizeof(vBuf), "%s: %.0f%%", uiRu("Квалификация", "Competency"), vitals.avgCompetency);
      ImGui::ProgressBar(vitals.avgCompetency * 0.01f, ImVec2(barW, 16.0f), vBuf);
      ImGui::EndGroup();

      ImGui::Spacing();
      const float avgVital = (vitals.avgHealth + vitals.avgNourishment + vitals.avgMorale + vitals.avgCompetency) * 0.25f;
      ImGui::TextColored(avgVital >= 70.0f ? ImVec4(0.40f, 1.0f, 0.60f, 1.0f) : ImVec4(0.95f, 0.75f, 0.30f, 1.0f),
                         "★ %s: %.1f%%  (%s)",
                         uiRu("Средний индекс благополучия", "Average Vitality Index"), avgVital,
                         avgVital >= 70.0f ? uiRu("Высокий расцвет", "Flourishing") : uiRu("Развивающаяся среда", "Developing"));

      ImGui::EndChild();
      ImGui::PopStyleColor();

      // Technological Surge Banner
      ImGui::Spacing();
      if (vitals.inTechnologicalSurge) {
        ImGui::PushStyleColor(ImGuiCol_ChildBg, ImVec4(0.18f, 0.14f, 0.04f, 0.90f));
        ImGui::BeginChild("##techSurgeActiveBanner", ImVec2(0.0f, 54.0f), true);
        ImGui::TextColored(ImVec4(1.0f, 0.88f, 0.25f, 1.0f), "👑 %s",
                           uiRu("ТЕХНОЛОГИЧЕСКИЙ ПОДЪЁМ АКТИВЕН!", "TECHNOLOGICAL SURGE ACTIVE!"));
        ImGui::TextColored(ImVec4(0.85f, 0.95f, 0.80f, 1.0f), "%s",
                           uiRu("Все жизненные показатели колонии превышают 70%. Активен бонус: +50% к генерации RP и подготовка элитных кадров в Академии.",
                                "All vital indicators exceed 70%. Active bonus: +50% RP yield and elite specialist training in the Academy."));
        ImGui::EndChild();
        ImGui::PopStyleColor();
      } else {
        ImGui::PushStyleColor(ImGuiCol_ChildBg, ImVec4(0.06f, 0.08f, 0.12f, 0.70f));
        ImGui::BeginChild("##techSurgeReqBanner", ImVec2(0.0f, 50.0f), true);
        ImGui::TextColored(ImVec4(0.70f, 0.85f, 0.95f, 1.0f), "❖ %s",
                           uiRu("Условия Технологического Подъёма:", "Technological Surge Requirements:"));
        ImGui::TextColored(ImVec4(0.60f, 0.70f, 0.80f, 1.0f), "%s",
                           uiRu("Для активации подъёма (+50% RP) поднимите показатели здоровья, питания, морали и квалификации выше 70% строительством новых объектов.",
                                "To activate surge (+50% RP), raise health, nourishment, morale, and competency above 70% by building new structures."));
        ImGui::EndChild();
        ImGui::PopStyleColor();
      }

      // Notable Candidates / Academy Graduates
      ImGui::Spacing();
      ImGui::TextColored(ImVec4(0.35f, 0.85f, 1.0f, 1.0f), "🎓 %s",
                         uiRu("Выпускники Планетарной Академии & Ведущие Специалисты:",
                              "Planetary Academy Graduates & Leading Specialists:"));
      ImGui::BeginChild("##academyCandidatesScroll", ImVec2(0.0f, 0.0f), true);

      const auto candidates = generateColonyNotableCandidates(m_selectedColony, stage);
      for (size_t ci = 0; ci < candidates.size(); ++ci) {
        const auto& cand = candidates[ci];
        ImGui::PushID(static_cast<int>(ci));

        // Check if already in reserve or officers
        bool alreadyInCrew = false;
        for (const auto& pair : m_crew.allAssigned()) {
          if (pair.second.id == cand.id) { alreadyInCrew = true; break; }
        }
        if (!alreadyInCrew) {
          for (const auto& r : m_crew.reserve) {
            if (r.id == cand.id) { alreadyInCrew = true; break; }
          }
        }

        ImGui::PushStyleColor(ImGuiCol_ChildBg, ImVec4(0.08f, 0.11f, 0.16f, 0.75f));
        ImGui::BeginChild("##candCard", ImVec2(0.0f, 92.0f), true);

        ImGui::TextColored(ImVec4(0.95f, 0.85f, 0.40f, 1.0f), "★ %s", cand.fullName().c_str());
        ImGui::SameLine();
        ImGui::TextColored(ImVec4(0.40f, 0.85f, 1.0f, 1.0f), "| %s (Lvl %d)",
                           uiRu(professionNameRu(cand.profession), professionNameEn(cand.profession)), cand.level);
        ImGui::SameLine();
        ImGui::TextColored(ImVec4(0.70f, 0.75f, 0.85f, 1.0f), "| %s: %s",
                           uiRu("Происхождение", "Origin"), cand.originWorldId.c_str());

        ImGui::TextColored(ImVec4(0.50f, 1.0f, 0.70f, 1.0f), "  [%s]",
                           uiRu(quirkNameRu(cand.quirk), quirkNameEn(cand.quirk)));
        ImGui::SameLine();
        ImGui::TextColored(ImVec4(0.60f, 0.70f, 0.80f, 1.0f), "— %s",
                           uiRu(quirkDescRu(cand.quirk), quirkDescEn(cand.quirk)));

        ImGui::TextColored(ImVec4(0.75f, 0.80f, 0.88f, 1.0f), "  %s: %s",
                           uiRu("Деятельность", "Activity"),
                           uiRu(cand.currentActivityRu.c_str(), cand.currentActivityEn.c_str()));

        const float recruitBtnW = 220.0f;
        ImGui::SameLine(ImGui::GetContentRegionAvail().x - recruitBtnW);
        if (alreadyInCrew) {
          ImGui::TextColored(ImVec4(0.40f, 0.90f, 0.50f, 1.0f), "%s",
                             uiRu("✓ В экипаже корабля", "✓ In ship crew"));
        } else {
          const int recruitCost = 100;
          const bool canRecruit = m_codex.getTotalResearchPoints() >= recruitCost;
          ImGui::BeginDisabled(!canRecruit);
          char rBtn[64];
          std::snprintf(rBtn, sizeof(rBtn), "%s (%d RP)###rec_%s",
                        uiRu("✦ Нанять в экипаж", "✦ Recruit to Crew"), recruitCost, cand.id.c_str());
          if (ImGui::Button(rBtn, ImVec2(recruitBtnW, 26.0f))) {
            m_codex.spendResearchPoints(recruitCost);
            m_crew.reserve.push_back(cand);
            saveProfileNow(true);
            Toast t;
            t.title = uiRu("Специалист нанят", "Specialist Recruited");
            char tdesc[128];
            std::snprintf(tdesc, sizeof(tdesc), "%s (%s) %s",
                          cand.fullName().c_str(), uiRu(professionNameRu(cand.profession), professionNameEn(cand.profession)),
                          uiRu("принят(а) в каюты корабля.", "joined ship quarters."));
            t.desc = tdesc;
            t.time = static_cast<float>(glfwGetTime());
            m_toasts.push_back(t);
            m_audio.playChime();
          }
          ImGui::EndDisabled();
        }

        ImGui::EndChild();
        ImGui::PopStyleColor();
        ImGui::PopID();
        ImGui::Spacing();
      }
      ImGui::EndChild();
    }
    ImGui::EndTabItem();
  }
  ImGui::EndTabBar();
  }
}
  ImGui::End();
  if (pushed) ImGui::PopFont();
}

void AppGL::drawCodex() {
  const ImVec2 disp = ImGui::GetIO().DisplaySize;
  ImGui::SetNextWindowPos(ImVec2(disp.x * 0.5f, disp.y * 0.5f), ImGuiCond_FirstUseEver,
                          ImVec2(0.5f, 0.5f));
  ImGui::SetNextWindowSize(ImVec2(620.0f, 520.0f), ImGuiCond_FirstUseEver);
  const bool pushed = modernPushFont();

  if (ImGui::Begin(uiRu("Кодекс космических открытий (K)###Codex",
                        "Ship Codex of Cosmic Discoveries (K)###Codex"),
                   &m_codexOpen)) {
    int scannedCount = m_codex.getScannedCount();
    int totalCount = m_codex.getTotalCount();
    int points = m_codex.getTotalResearchPoints();

    ImGui::TextColored(ImVec4(1.0f, 0.85f, 0.35f, 1.0f),
                       "%s: %d RP  |  %s: %d / %d",
                       uiRu("ОЧКИ ИССЛЕДОВАНИЙ", "RESEARCH POINTS"), points,
                       uiRu("ОТКРЫТО ОБЪЕКТОВ", "DISCOVERIES"), scannedCount, totalCount);
    ImGui::Separator();
    ImGui::Spacing();

    std::vector<std::string> categoriesRu = {
        "Планетная система", "Чёрная дыра", "Квазар", "Туманность",
        "Килоновая", "Сверхновая", "Приливной разрыв", "Пульсар",
        "Магнетар", "Скопление", "Галактика", "Созвездие"
    };

    const auto& entries = m_codex.getEntries();
    for (const auto& cat : categoriesRu) {
      bool hasCat = false;
      for (const auto& e : entries) {
        if (e.categoryRu == cat) { hasCat = true; break; }
      }
      if (!hasCat) continue;

      if (ImGui::CollapsingHeader(cat.c_str(), ImGuiTreeNodeFlags_DefaultOpen)) {
        for (const auto& e : entries) {
          if (e.categoryRu != cat) continue;

          ImGui::PushID(e.stationId.c_str());
          ImGui::Indent(12.0f);

          if (e.scanned) {
            ImGui::TextColored(ImVec4(0.2f, 0.95f, 0.4f, 1.0f), "✓ %s",
                               uiRu(e.nameRu.c_str(), e.nameEn.c_str()));
            ImGui::SameLine();
            ImGui::TextColored(ImVec4(0.95f, 0.8f, 0.3f, 1.0f), "[+100 RP]");
            ImGui::PushStyleColor(ImGuiCol_Text, ImVec4(0.85f, 0.88f, 0.92f, 1.0f));
            ImGui::TextWrapped("%s", uiRu(e.descriptionRu.c_str(), e.descriptionEn.c_str()));
            ImGui::PopStyleColor();
          } else {
            ImGui::TextColored(ImVec4(0.55f, 0.6f, 0.68f, 1.0f), "? %s — %s",
                               uiRu(e.nameRu.c_str(), e.nameEn.c_str()),
                               uiRu("Не исследовано", "Uncharted"));
            ImGui::PushStyleColor(ImGuiCol_Text, ImVec4(0.5f, 0.55f, 0.6f, 1.0f));
            ImGui::TextWrapped("%s",
                               uiRu("Требуется: совершить прыжок в систему и провести спектральный анализ [C].",
                                    "Requirement: jump to system and perform spectral analysis [C]."));
            ImGui::PopStyleColor();
          }

          const Station* curSt = m_sceneManager->getCurrentStation();
          if (!curSt || curSt->id != e.stationId) {
            std::string btnText = std::string(">> ") + uiRu("Лететь к объекту", "Warp to System");
            if (ImGui::SmallButton(btnText.c_str())) {
              teleportToStation(e.stationId);
            }
          }
          ImGui::Unindent(12.0f);
          ImGui::Spacing();
          ImGui::PopID();
        }
      }
    }
  }
  ImGui::End();
  if (pushed) ImGui::PopFont();
}

void AppGL::drawBridgeCommsToast() {
  double now = glfwGetTime();
  bool hadActiveBefore = m_bridgeComms.hasActiveMessage();
  m_bridgeComms.update(now);
  bool hasActiveNow = m_bridgeComms.hasActiveMessage();

  // v5.0.0: Bridge Comms Radio Squelch & Static audio
  if (!hadActiveBefore && hasActiveNow) {
    m_audio.playRadioBeep();
    m_audio.setRadioStatic(0.38f);
  } else if (hadActiveBefore && !hasActiveNow) {
    m_audio.playRadioEnd();
    m_audio.setRadioStatic(0.0f);
  }

  if (!hasActiveNow) return;
  const RadioMessage* msg = m_bridgeComms.getActiveMessage();
  if (!msg) return;

  const ImVec2 disp = ImGui::GetIO().DisplaySize;
  const float w = std::min(460.0f, disp.x - 40.0f);
  const float toastY = (m_expedition.current() != nullptr) ? 140.0f : 56.0f;
  ImGui::SetNextWindowPos(ImVec2(disp.x * 0.5f, toastY), ImGuiCond_Always, ImVec2(0.5f, 0.0f));
  ImGui::SetNextWindowSize(ImVec2(w, 0.0f), ImGuiCond_Always);

  ImGuiWindowFlags flags = ImGuiWindowFlags_NoDecoration |
                           ImGuiWindowFlags_AlwaysAutoResize |
                           ImGuiWindowFlags_NoSavedSettings |
                           ImGuiWindowFlags_NoFocusOnAppearing |
                           ImGuiWindowFlags_NoNav;

  const bool pushed = modernPushFont();
  ImGui::PushStyleColor(ImGuiCol_WindowBg, ImVec4(0.06f, 0.09f, 0.14f, 0.92f));
  ImGui::PushStyleColor(ImGuiCol_Border, ImVec4(0.22f, 0.74f, 0.97f, 0.85f));
  ImGui::PushStyleVar(ImGuiStyleVar_WindowRounding, 8.0f);
  ImGui::PushStyleVar(ImGuiStyleVar_WindowBorderSize, 1.5f);

  if (ImGui::Begin("##BridgeCommsToast", nullptr, flags)) {
    ImGui::TextColored(ImVec4(0.35f, 0.85f, 1.0f, 1.0f), "⟡ %s",
                       uiRu("РАДИОПЕРЕГОВОРЫ МОСТИКА", "BRIDGE COMMS CHANNEL"));
    ImGui::SameLine(ImGui::GetContentRegionAvail().x - 16.0f);
    if (ImGui::SmallButton("x")) {
      m_bridgeComms.dismiss();
      m_audio.playRadioEnd();
      m_audio.setRadioStatic(0.0f);
    }

    ImGui::TextColored(ImVec4(1.0f, 0.82f, 0.35f, 1.0f), "▲ %s",
                       uiRu(msg->callsignRu.c_str(), msg->callsignEn.c_str()));

    ImGui::PushStyleColor(ImGuiCol_Text, ImVec4(0.92f, 0.95f, 0.98f, 1.0f));
    ImGui::TextWrapped("%s", uiRu(msg->textRu.c_str(), msg->textEn.c_str()));
    ImGui::PopStyleColor();

    float prog = m_bridgeComms.getMessageProgress(now);
    ImVec2 p0 = ImGui::GetCursorScreenPos();
    float availW = ImGui::GetContentRegionAvail().x;
    ImDrawList* dl = ImGui::GetWindowDrawList();
    float lineY = p0.y + 4.0f;
    dl->AddLine(ImVec2(p0.x, lineY), ImVec2(p0.x + availW, lineY),
                IM_COL32(50, 70, 95, 120), 2.0f);
    float activeW = availW * (1.0f - prog);
    dl->AddLine(ImVec2(p0.x, lineY), ImVec2(p0.x + activeW, lineY),
                IM_COL32(56, 189, 248, 240), 2.5f);

    ImGui::Dummy(ImVec2(availW, 6.0f));
  }
  ImGui::End();

  ImGui::PopStyleVar(2);
  ImGui::PopStyleColor(2);
  if (pushed) ImGui::PopFont();
}

