void AppGL::saveAdventureSlotNow(bool quiet) {
  // v4.0: зеркало saveProfileNow с mode = Adventure и своим слотом;
  // структура сейва и kSaveSchema=1 не тронуты (слот резервирован).
  if (!m_saveInteractive) return;
  std::string err;
  SaveGame g;
  g.mode = SaveMode::Adventure;
  g.savedUtc = saveUtcNowISO8601();
  g.progress.visited = m_visited;
  g.progress.unlocked.assign(m_unlockedIds.begin(), m_unlockedIds.end());
  g.progress.route = m_route;
  g.progress.colonies = m_colonies;
  g.progress.colonyStages = m_colonyStages;
  g.progress.researchPoints = m_codex.getTotalResearchPoints();
  g.progress.discoveries.assign(m_discoveredConstellations.begin(), m_discoveredConstellations.end());
  g.progress.minBhDistance = m_minBhDistance;
  g.session.custom = m_shipCustomization;
  if (const Station* cur = m_sceneManager->getCurrentStation()) {
    g.session.station = cur->id;
  }
  g.session.camPos = m_camera.position;
  g.session.yaw = m_camera.yaw;
  g.session.pitch = m_camera.pitch;
  const bool saveOk =
      saveWriteFile(saveFilePath(SaveMode::Adventure), saveSerialize(g), err);
  if (saveOk) {
    if (!quiet) {
      Toast t;
      t.title = uiRu("Новая игра", "New Game");
      t.desc = uiRu("Сюжетный профиль создан (save-adventure.json).",
                    "Story profile written (save-adventure.json).");
      t.time = static_cast<float>(glfwGetTime());
      m_toasts.push_back(t);
    }
  } else {
    m_saveStatus = std::string(uiRu("Ошибка сохранения", "Save failed")) + ": " + err;
    if (!quiet) m_audio.playBlip();
  }
}

unsigned int AppGL::uploadRgba(const unsigned char* px, int w, int h) {
  unsigned int tex = 0;
  GLint prevTex = 0;
  glGetIntegerv(GL_TEXTURE_BINDING_2D, &prevTex);
  GLint prevAlign = 4;
  glGetIntegerv(GL_UNPACK_ALIGNMENT, &prevAlign);

  glGenTextures(1, &tex);
  glBindTexture(GL_TEXTURE_2D, tex);
  glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_LINEAR);
  glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_LINEAR);
  glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, GL_CLAMP_TO_EDGE);
  glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_T, GL_CLAMP_TO_EDGE);
  glPixelStorei(GL_UNPACK_ALIGNMENT, 1);
  glTexImage2D(GL_TEXTURE_2D, 0, GL_RGBA8, w, h, 0, GL_RGBA,
               GL_UNSIGNED_BYTE, px);
  glPixelStorei(GL_UNPACK_ALIGNMENT, prevAlign);
  glBindTexture(GL_TEXTURE_2D, static_cast<GLuint>(prevTex));
  return tex;
}

void AppGL::invalidateVideoSlide() {
  if (m_videoTex != 0) {
    glDeleteTextures(1, &m_videoTex);
    m_videoTex = 0;
  }
  m_slideVStart = -1.0;
  m_videoFrames = 0;
  m_videoIdx = -1;
  m_videoW = 0;
  m_videoH = 0;
}

unsigned int AppGL::loadUiTexture(const std::string& rel, int* w, int* h) {
  auto it = m_uiTex.find(rel);
  if (it != m_uiTex.end() && it->second.id != 0 && glIsTexture(it->second.id) == GL_TRUE) {
    if (w) *w = it->second.w;
    if (h) *h = it->second.h;
    return it->second.id;
  }
  UiTex t;
  const std::string resolved = resolveAssetPath(rel);
  unsigned char* px = stbi_load(resolved.c_str(), &t.w, &t.h, nullptr, 4);
  if (px) {
    t.id = uploadRgba(px, t.w, t.h);
    stbi_image_free(px);
    m_uiTex[rel] = t;
  } else {
    m_uiTex.erase(rel);
  }
  if (w) *w = t.w;
  if (h) *h = t.h;
  return t.id;
}

void AppGL::openChapterSlide(int slideIdx) {
  // === Expedition === (v3.5.0): одиночный слайд — итог главы поверх игры.
  const auto& slides = storyChapterSlides();
  if (slideIdx < 0 || slideIdx >= static_cast<int>(slides.size())) return;
  m_slidesCurrent.assign(1, slides[slideIdx]);
  m_slidesHead.clear();
  for (const auto& c : expeditionChapters()) {
    if (c.slideIdx == slideIdx) {
      m_slidesHead = uiRu(c.titleRu.c_str(), c.titleEn.c_str());      break;
    }
  }
  m_slidesIntro = false;
  m_slidesPreroll = false;
  m_slidesIdx = 0;
  m_slidesOpen = true;
  m_slideAnimIdx = -1;
}

void AppGL::openEndingSlide(int choice) {
  // v4.4+: 6 концовок Adventure: colony (7), horizon (8), solar rebirth (10),
  // loop transcendence (11), ark citadel (12), hyper-breakthrough (13) в storyChapterSlides().
  // Служебный слайд 6 остаётся fallback для старых сейвов.
  // После выбранной концовки идёт общий эпилог «Наследие» (слайд 9).
  const auto& slides = storyChapterSlides();
  const int idx = slideIndexForFinale(choice);
  if (idx < 0 || idx >= static_cast<int>(slides.size())) return;
  m_slidesCurrent.assign(1, slides[idx]);
  // === Astro-Zettelkasten True Ending Injection ===
  if (choice == kFinaleSolarRebirth && m_zettelkasten.isClusterTrueEndingUnlocked(kClusterSolar)) {
    StorySlide ts;
    ts.textRu = ZettelGraph::getTrueEndingEpilogueRu(kClusterSolar);
    ts.textEn = ZettelGraph::getTrueEndingEpilogueEn(kClusterSolar);
    ts.art = 1;
    m_slidesCurrent.push_back(ts);
  } else if (choice == kFinaleFifthAlliance && m_zettelkasten.isClusterTrueEndingUnlocked(kClusterStasis)) {
    StorySlide ts;
    ts.textRu = ZettelGraph::getTrueEndingEpilogueRu(kClusterStasis);
    ts.textEn = ZettelGraph::getTrueEndingEpilogueEn(kClusterStasis);
    ts.art = 2;
    m_slidesCurrent.push_back(ts);
  } else if (choice == kFinaleColony && m_zettelkasten.isClusterTrueEndingUnlocked(kClusterEden)) {
    StorySlide ts;
    ts.textRu = ZettelGraph::getTrueEndingEpilogueRu(kClusterEden);
    ts.textEn = ZettelGraph::getTrueEndingEpilogueEn(kClusterEden);
    ts.art = 0;
    m_slidesCurrent.push_back(ts);
  } else if ((choice == kFinaleHyperBreakthrough || choice == kFinaleLoopTranscendence) &&
             m_zettelkasten.isClusterTrueEndingUnlocked(kClusterMultiverse)) {
    StorySlide ts;
    ts.textRu = ZettelGraph::getTrueEndingEpilogueRu(kClusterMultiverse);
    ts.textEn = ZettelGraph::getTrueEndingEpilogueEn(kClusterMultiverse);
    ts.art = 3;
    m_slidesCurrent.push_back(ts);
  }
  if (slides.size() > 9) m_slidesCurrent.push_back(slides[9]);
  m_slidesHead = uiRu(finaleTitleRu(choice).c_str(),
                      finaleTitleEn(choice).c_str());
  m_slidesIntro = false;
  m_slidesPreroll = false;
  m_slidesIdx = 0;
  m_slidesOpen = true;
  m_slideAnimIdx = -1;
  m_slideShownAt = glfwGetTime();
  m_slideTextStart = glfwGetTime();
}

void AppGL::saveExpeditionFileNow() {
  // === Expedition === (v3.5.0): state в отдельном expedition.json рядом
  // с профилями игры (схема SaveGame не тронута — kSaveSchema=1).
  // #161: раньше файл писался напрямую с trunc — падение процесса посреди
  // записи обнуляло прогресс экспедиции. Теперь через атомарный писатель.
  const std::string dir = saveProfileDir();
  std::error_code ec;
  std::filesystem::create_directories(dir, ec);
  const std::string text = serializeExpedition(m_expedition);
  std::string err;
  saveWriteFile(expeditionFilePathFor(dir), text, err);
}

void AppGL::loadExpeditionFileNow() {
  const std::string dir = saveProfileDir();
  std::ifstream f(expeditionFilePathFor(dir), std::ios::binary);
  if (!f.is_open()) return;
  std::ostringstream buf;
  buf << f.rdbuf();
  ExpeditionState st;
  if (deserializeExpedition(buf.str(), st)) {
    m_expedition = st;
    // v4.1: старый сейв мог дойти до финала до появления развилки —
    // предлагаем выбрать концовку при входе в игру.
    if (m_expedition.finished() &&
        m_expedition.finaleChoice == kFinaleUnset) {
      m_finaleChoiceOpen = true;
    }
  }
}

